 f=pd.DataFrame(json.loads(F.read_text()));f.report_date=pd.to_datetime(f.report_date);cur=f.sort_values(['kod','report_date']).groupby('kod',as_index=False).tail(1).copy();prev=f.sort_values(['kod','report_date']).groupby('kod').nth(-2).reset_index().set_index('kod')
