 ev=cur[['kod','analysis_date','source_ids','publication_dates','evidence_status']].copy();ev['claim']='UNKNOWN';ev['evidence_for']='[]';ev['evidence_against']='[]';pq(ev,'OTSC1_CURRENT_EVIDENCE');pq(pd.DataFrame(columns=['ticker','kpi','value','source_id','publication_date','validation_status']),'OTSC1_COMMERCIAL_KPI_EXTRACTIONS');pq(pd.DataFrame(columns=['ticker','original_statement','date','target','later_outcome','result']),'OTSC1_PROMISE_DELIVERY_LEDGER');pq(pd.DataFrame({'ticker':cur.kod,'FINANCING_RISK':'UNKNOWN','DILUTION_RISK':np.where(cur.share_change>.10,'ELEVATED','UNKNOWN'),'CUSTOMER_CONCENTRATION':'UNKNOWN','REGULATORY_RISK':'UNKNOWN','BINARY_OUTCOME_RISK':'UNKNOWN','SINGLE_PRODUCT_RISK':'UNKNOWN','ACCOUNTING_RISK':'UNKNOWN','EXECUTION_RISK':'UNKNOWN','BALANCE_SHEET_RISK':np.where(cur.equity_ratio<.20,'ELEVATED','UNKNOWN'),'VALUATION_RISK':'UNKNOWN'}),'OTSC1_RISK_MAP');pq(pd.DataFrame(columns=['ticker','trigger','expected_timing','evidence','dependencies','confidence']),'OTSC1_RERATING_TRIGGERS')
